/**
 * Global setup for every Vitest suite (see vitest.config.ts).
 *
 * 1. Replaces the WebAssembly bridge with inert functions, so no suite needs
 *    the package generated by wasm-pack.
 * 2. Blocks fetch, XMLHttpRequest, WebSocket, EventSource and
 *    navigator.sendBeacon: any attempt throws "network disabled in tests".
 */
import { vi } from 'vitest';
import { installNetworkGuard } from './networkGuard';

vi.mock('../../wasm/wasmBridge', async () => {
  const { createWasmBridgeStub } = await import('./wasmBridgeStub');
  return createWasmBridgeStub();
});

installNetworkGuard();
